import ghidra.app.script.GhidraScript;
import ghidra.app.decompiler.*;
import java.nio.file.*;
public class N3DPass12ExportComments extends GhidraScript {
 public void run()throws Exception{
  var d=new DecompInterface();if(!d.openProgram(currentProgram))throw new Exception(d.getLastMessage());
  try{for(String s:new String[]{"1010:d974","1010:1d4e","1010:bb26"}){var f=getFunctionAt(toAddr(s));var r=d.decompileFunction(f,30,monitor);if(!r.decompileCompleted())throw new Exception(r.getErrorMessage());Files.writeString(Paths.get(getScriptArgs()[0],s.replace(':','_')+".c"),"/* "+s+" "+f.getName()+" */\n"+r.getDecompiledFunction().getC());}}finally{d.dispose();}
  println("PASS12_FINAL_COMMENTS_EXPORTED 3");
 }
